# Runtime v2 · SH Quản lý state: stateless/stateful, hoisting, ai giữ state, sống qua tái tạo (chương mới)
# Nguồn: Kunneth Ch.5 (toàn văn); Jetpack Compose by Tutorials Ch.7 (UI update loop, UDF); Jetpack Compose 1.3 Essentials Ch.20 (UDF, hoisting,
# rememberSaveable); "State and Jetpack Compose", "Where to hoist state", "Save UI state in Compose" (developer.android.com, đọc 2026-11-23).
# Ví dụ của sách dùng LiveData/observeAsState và lifecycle 2.4.0: ghi rõ là phiên bản của sách; mẫu hiện tại là StateFlow + collectAsStateWithLifecycle.

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.survive ----------------
    m = lambda k, vi, en=None: a('m.survive.' + k, vi, en)
    m('title', 'Gõ "Ana" rồi... state nào còn?', 'Type "Ana", then... which state survives?')
    m('overview', 'Người dùng gõ "Ana" vào một ô nhập, và cùng chữ đó được giữ ở năm nơi: `remember`, `rememberSaveable`, một `StateFlow` trong ViewModel, `SavedStateHandle` của ViewModel, và lưu trữ bền (DataStore/Room). Chọn một sự kiện rồi bấm Step để xem nơi nào còn giữ được chữ.', 'The user types "Ana" into a field, and the same text is held in five places: `remember`, `rememberSaveable`, a `StateFlow` in a ViewModel, the ViewModel\'s `SavedStateHandle`, and durable storage (DataStore/Room). Pick an event, then press Step to see which places still hold the text.')
    m('wrapup', 'Mỗi nơi giữ state gắn với một vòng đời: `remember` sống theo Composition; `rememberSaveable` và `SavedStateHandle` đi qua saved instance state (Bundle) nên qua được đổi cấu hình và process bị hệ thống dừng; ViewModel sống trong bộ nhớ nên qua đổi cấu hình nhưng không qua process death; chỉ lưu trữ bền qua được việc người dùng đóng hẳn app. Chọn nơi giữ theo việc state cần sống bao lâu, và đừng nhét dữ liệu lớn vào Bundle.', 'Each place that holds state is tied to a lifetime: `remember` lives with the Composition; `rememberSaveable` and `SavedStateHandle` go through saved instance state (a Bundle), so they survive configuration changes and system-initiated process death; a ViewModel lives in memory, so it survives configuration changes but not process death; only durable storage survives the user closing the app for good. Choose the holder by how long the state must live, and keep large data out of the Bundle.')
    m('simp.1', 'Bảng giữ/mất theo tài liệu "Save UI state in Compose" và "State and Jetpack Compose"; giả định không có `android:configChanges` tự xử lý xoay màn hình, và màn hình không bị gỡ khỏi Composition giữa chừng.', 'The keep/lose table follows "Save UI state in Compose" and "State and Jetpack Compose"; it assumes no `android:configChanges` handling rotation manually, and that the screen is not removed from the Composition midway.')
    m('simp.2', 'Lưu trữ bền chỉ giữ được thứ đã GHI XONG xuống đĩa; site không vẽ thời điểm ghi. Bản nháp trong ô nhập thường không cần sống qua lúc người dùng đóng hẳn app: tài liệu coi mất state tạm khi đó là hợp lý.', 'Durable storage only keeps what was FULLY WRITTEN to disk; the site does not model when the write happens. A draft in a text field usually does not need to survive the user closing the app: the docs consider losing transient state then reasonable.')
    m('ctl.hint', 'Chạy lần lượt bốn sự kiện và so số nơi còn giữ được chữ.', 'Run the four events in turn and compare how many places still hold the text.')
    m('ctl.event', 'Sự kiện', 'Event')
    for k, vi, en in [('recompose', 'Recompose (state khác đổi)', 'Recompose (another state changes)'), ('rotate', 'Xoay màn hình (đổi cấu hình)', 'Rotate the screen (configuration change)'),
                      ('processDeath', 'Hệ thống dừng process khi app ở nền', 'The system kills the process while the app is in the background'), ('dismiss', 'Người dùng vuốt app khỏi màn hình gần đây', 'The user swipes the app away from recents')]:
        m('ctl.event.' + k, vi, en)
    m('diagramTitle', 'Màn hình và năm nơi giữ state', 'The screen and five places to hold state')
    m('diagramDesc', 'Màn hình nối với Composition (remember), Bundle của saved instance state (rememberSaveable, SavedStateHandle), ViewModelStore và lưu trữ bền; process chứa tất cả những gì trong bộ nhớ', 'The screen connects to the Composition (remember), the saved-instance-state Bundle (rememberSaveable, SavedStateHandle), the ViewModelStore and durable storage; the process holds everything in memory')
    for k, vi, en in [('ui', 'Màn hình (activity)', 'Screen (activity)'), ('composition', 'Composition (nơi remember giữ)', 'Composition (remember)'), ('bundle', 'Bundle trạng thái đã lưu', 'Saved state Bundle'),
                      ('vm', 'ViewModel (bộ nhớ)', 'ViewModel (memory)'), ('disk', 'Lưu trữ bền (DataStore/Room)', 'Durable storage (DataStore/Room)'), ('process', 'Process của app', 'App process')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('kept', 'Còn giữ', 'Kept'), ('lost', 'Mất', 'Lost'), ('checked', 'Đã kiểm', 'Checked')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('remember', 'remember', 'remember'), ('saveable', 'rememberSaveable', 'rememberSaveable'), ('vm', 'ViewModel (StateFlow thường)', 'ViewModel (StateFlow)'),
                      ('handle', 'SavedStateHandle', 'SavedStateHandle'), ('disk', 'Lưu trữ bền', 'Durable storage')]:
        m('h.' + k, vi, en)
    S = [
        ('type', 'Người dùng gõ "Ana"', 'The user types "Ana"', 'Cùng một chữ được ghi vào năm nơi. Lúc này cả năm đều giữ "Ana".', 'The same text is written to five places. Right now all five hold "Ana".'),
        ('event.recompose', 'Sự kiện: recompose', 'Event: recompose', 'Một state khác đổi và màn hình chạy lại. Composition vẫn còn, activity vẫn còn, process vẫn còn.', 'Another state changes and the screen re-runs. The Composition is still there, the activity is still there, the process is still there.'),
        ('event.rotate', 'Sự kiện: xoay màn hình', 'Event: rotate the screen', 'Đổi cấu hình: activity bị hủy và tạo lại, kéo theo Composition mới. Trước khi hủy, hệ thống lưu saved instance state (Bundle). Process và ViewModelStore vẫn còn.', 'A configuration change: the activity is destroyed and recreated, bringing a new Composition. Before destruction, the system saves the saved instance state (a Bundle). The process and the ViewModelStore remain.'),
        ('event.processDeath', 'Sự kiện: hệ thống dừng process', 'Event: the system kills the process', 'App ở nền, thiết bị cần bộ nhớ nên hệ thống dừng process. Mọi thứ trong bộ nhớ mất. Khi người dùng quay lại, activity được tạo lại từ saved instance state đã lưu trước đó.', 'The app is in the background and the device needs memory, so the system kills the process. Everything in memory is gone. When the user comes back, the activity is recreated from the previously saved instance state.'),
        ('event.dismiss', 'Sự kiện: người dùng đóng hẳn app', 'Event: the user closes the app for good', 'Người dùng vuốt app khỏi màn hình ứng dụng gần đây. Đây là ý định của người dùng: saved instance state cũng bị bỏ. Lần mở sau là bắt đầu mới.', 'The user swipes the app away from recents. This is the user\'s intent: the saved instance state is discarded too. The next launch starts fresh.'),
    ]
    reasons = {
        'remember': ('remember', 'giữ trong slot của Composition', 'kept in a slot of the Composition'),
        'saveable': ('rememberSaveable', 'lưu vào saved instance state (Bundle)', 'saved into the saved instance state (Bundle)'),
        'vm': ('ViewModel', 'giữ trong bộ nhớ, gắn với ViewModelStoreOwner', 'kept in memory, scoped to a ViewModelStoreOwner'),
        'handle': ('SavedStateHandle', 'ViewModel ghi vào saved state', 'the ViewModel writes it into saved state'),
        'disk': ('DataStore/Room', 'ghi xuống đĩa', 'written to disk'),
    }
    detail = {
        ('remember', 'recompose'): (1, 'Composition còn nguyên nên slot của `remember` trả lại "Ana".', 'The Composition is intact, so `remember`\'s slot returns "Ana".'),
        ('remember', 'rotate'): (0, 'Activity mới có Composition mới: `remember` chạy lại lambda và trả "" ban đầu. `remember` không giữ qua đổi cấu hình.', 'The new activity has a new Composition: `remember` runs its lambda again and returns the initial "". `remember` does not survive configuration changes.'),
        ('remember', 'processDeath'): (0, 'Composition nằm trong bộ nhớ của process; process mất thì nó mất.', 'The Composition lives in the process\'s memory; when the process dies, so does it.'),
        ('remember', 'dismiss'): (0, 'Không còn gì trong bộ nhớ.', 'Nothing is left in memory.'),
        ('saveable', 'recompose'): (1, 'Như `remember`, nó giữ giá trị qua recompose.', 'Like `remember`, it keeps the value across recompositions.'),
        ('saveable', 'rotate'): (1, 'Giá trị đã được ghi vào Bundle trước khi activity bị hủy và được khôi phục vào Composition mới.', 'The value was written into the Bundle before the activity was destroyed and is restored into the new Composition.'),
        ('saveable', 'processDeath'): (1, 'Bundle được hệ thống giữ ngoài process, nên khi activity được tạo lại, giá trị được khôi phục.', 'The system keeps the Bundle outside the process, so when the activity is recreated the value is restored.'),
        ('saveable', 'dismiss'): (0, 'Tài liệu ghi rõ: `rememberSaveable` không giữ state khi activity bị người dùng đóng hẳn, ví dụ vuốt khỏi màn hình gần đây.', 'The docs say it plainly: `rememberSaveable` does not retain state when the user fully dismisses the activity, for example by swiping it from recents.'),
        ('vm', 'recompose'): (1, 'ViewModel không liên quan tới recompose; StateFlow vẫn giữ "Ana".', 'The ViewModel is unaffected by recomposition; the StateFlow still holds "Ana".'),
        ('vm', 'rotate'): (1, 'ViewModel sống qua đổi cấu hình: instance cũ được gắn vào activity mới. Đây là lợi ích "miễn phí" của ViewModel.', 'A ViewModel survives configuration changes: the old instance is attached to the new activity. This is the "free" benefit of a ViewModel.'),
        ('vm', 'processDeath'): (0, 'ViewModel chỉ nằm trong bộ nhớ. Process mất thì ViewModel mới được tạo với giá trị ban đầu.', 'The ViewModel only lives in memory. When the process dies, a new ViewModel is created with the initial value.'),
        ('vm', 'dismiss'): (0, 'Không còn gì trong bộ nhớ.', 'Nothing is left in memory.'),
        ('handle', 'recompose'): (1, 'Không bị ảnh hưởng.', 'Unaffected.'),
        ('handle', 'rotate'): (1, 'ViewModel còn nguyên, và `SavedStateHandle` của nó cũng vậy.', 'The ViewModel is intact, and so is its `SavedStateHandle`.'),
        ('handle', 'processDeath'): (1, 'Đây là lý do có `SavedStateHandle`: ViewModel mới được tạo, nhưng handle được khôi phục từ saved state, nên "Ana" quay lại.', 'This is why `SavedStateHandle` exists: a new ViewModel is created, but the handle is restored from saved state, so "Ana" comes back.'),
        ('handle', 'dismiss'): (0, 'Saved state cũng bị bỏ khi người dùng đóng hẳn, nên handle bắt đầu rỗng.', 'Saved state is discarded too when the user closes the app for good, so the handle starts empty.'),
        ('disk', 'recompose'): (1, 'Không bị ảnh hưởng.', 'Unaffected.'),
        ('disk', 'rotate'): (1, 'Dữ liệu trên đĩa không phụ thuộc activity.', 'Data on disk does not depend on the activity.'),
        ('disk', 'processDeath'): (1, 'Dữ liệu trên đĩa không phụ thuộc process.', 'Data on disk does not depend on the process.'),
        ('disk', 'dismiss'): (1, 'Chỉ lưu trữ bền còn lại. Dùng nó cho dữ liệu người dùng mong còn mãi, không cho mọi state tạm thời.', 'Only durable storage remains. Use it for data users expect to persist, not for every piece of transient state.'),
    }
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for (h, ev), (ok, xv, xe) in detail.items():
        name, rv, re_ = reasons[h]
        tv = '%s: %s' % (name, 'còn "Ana"' if ok else 'mất, về ""')
        te = '%s: %s' % (name, 'still "Ana"' if ok else 'lost, back to ""')
        key = 'h.%s.%s' % (h, ev)
        m('s.%s.title' % key, tv, te); m('s.%s.explain' % key, xv + ' (' + rv + ')', xe + ' (' + re_ + ')'); m('ev.' + key, tv, te)
    E = [('recompose', 'Kết thúc: cả năm nơi còn giữ', 'The end: all five places kept it', 'Recompose không phá state ở đâu cả.', 'Recomposition destroys state nowhere.'),
         ('rotate', 'Kết thúc: chỉ remember mất', 'The end: only remember lost it', 'Đây là lỗi kinh điển "xoay màn hình thì ô nhập trống": dùng `rememberSaveable` cho state của phần tử UI, hoặc giữ trong ViewModel.', 'This is the classic "rotate and the field goes blank" bug: use `rememberSaveable` for UI element state, or keep it in the ViewModel.'),
         ('processDeath', 'Kết thúc: remember và ViewModel mất', 'The end: remember and the ViewModel lost it', 'Lỗi khó thấy khi phát triển vì máy test ít khi dừng process. Bật "Don\'t keep activities" hoặc dùng `adb shell am kill` khi app ở nền để thử; dùng `SavedStateHandle` cho state cần sống qua.', 'A bug that is hard to see in development because test devices rarely kill the process. Turn on "Don\'t keep activities" or use `adb shell am kill` while the app is in the background to try it; use `SavedStateHandle` for state that must survive.'),
         ('dismiss', 'Kết thúc: chỉ lưu trữ bền còn', 'The end: only durable storage kept it', 'Người dùng đóng hẳn app thì mất state tạm là chuyện bình thường; dữ liệu quan trọng phải được lưu bền.', 'Losing transient state when the user closes the app for good is normal; important data must be stored durably.')]
    for ev, tv, te, xv, xe in E:
        m('s.end.%s.title' % ev, tv, te); m('s.end.%s.explain' % ev, xv, xe); m('ev.end.' + ev, tv, te)
        m('co.end.' + ev, xv, xe)
    m('co.dismiss', 'Tài liệu "State and Jetpack Compose": `rememberSaveable` không giữ state nếu activity bị người dùng đóng hẳn. [[src:and-state]]', '"State and Jetpack Compose": `rememberSaveable` won\'t retain state if the activity is completely dismissed by the user. [[src:and-state]]')
    m('co.vmDeath', 'Tài liệu "Save UI state": ViewModel không sống qua process death do hệ thống; dùng Saved State module với `SavedStateHandle`. [[src:cp-saving]]', '"Save UI state": a ViewModel does not survive system-initiated process death; use the Saved State module with `SavedStateHandle`. [[src:cp-saving]]')
    a('cap.survive', 'Màn hình (trái) nối tới các nơi giữ state. Composition và ViewModel nằm trong bộ nhớ của process (góc trên phải); Bundle trạng thái đã lưu được hệ thống giữ khi activity bị tạo lại; lưu trữ bền nằm trên đĩa. Mỗi bước sáng lên nơi đang được kiểm.', 'The screen (left) connects to the places holding state. The Composition and the ViewModel live in the process\'s memory (top right); the saved-state Bundle is kept by the system when the activity is recreated; durable storage is on disk. Each step lights up the place being checked.')

    # ---------------- chương SH (mới) ----------------
    C = 'sh'
    a(C + '.title', 'Quản lý state: stateless, hoisting, ai giữ state và sống qua tái tạo', 'Managing state: stateless composables, hoisting, who owns state, and surviving recreation')
    a(C + '.essence',
      'State đi xuống, sự kiện đi lên (unidirectional data flow): composable nhận giá trị và lambda, không tự sửa state của cha. Composable stateless (không `remember` gì) dễ dùng lại, dễ test, dễ preview; state được hoist lên tổ tiên chung thấp nhất của mọi nơi đọc và ghi nó.\n'
      'Ai giữ state tùy loại logic: UI logic đơn giản thì composable tự giữ; UI logic phức tạp thì một plain state holder được `remember`; business logic và screen UI state thì ViewModel, bên ngoài Composition.\n'
      'Mỗi nơi giữ có vòng đời riêng: `remember` qua recompose; `rememberSaveable` qua đổi cấu hình và process bị hệ thống dừng; ViewModel qua đổi cấu hình; `SavedStateHandle` qua process death; chỉ lưu trữ bền qua việc người dùng đóng hẳn app. Chương này xây trên chương B4 (`remember` và `mutableStateOf`).',
      'State flows down, events flow up (unidirectional data flow): a composable receives values and lambdas and does not modify its parent\'s state itself. A stateless composable (one that `remember`s nothing) is easy to reuse, test and preview; state is hoisted to the lowest common ancestor of everything that reads and writes it.\n'
      'Who owns state depends on the kind of logic: simple UI logic, the composable owns it; complex UI logic, a remembered plain state holder; business logic and screen UI state, a ViewModel, outside the Composition.\n'
      'Each owner has its own lifetime: `remember` survives recomposition; `rememberSaveable` survives configuration changes and system-initiated process death; a ViewModel survives configuration changes; `SavedStateHandle` survives process death; only durable storage survives the user closing the app for good. This chapter builds on chapter B4 (`remember` and `mutableStateOf`).')
    a(C + '.goal.g1', 'Đã thấy sự kiện xảy ra với năm nơi giữ state', 'Saw the event hit the five state holders')
    a(C + '.goal.g2', 'Đã chạy một sự kiện tới cuối', 'Ran one event to the end')
    a(C + '.sim.runtime.survive', 'State nào sống sót', 'Which state survives')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Màn hình đăng ký có ô "Tên" giữ bằng `remember { mutableStateOf("") }`. Người dùng gõ "Ana", xoay ngang điện thoại, rồi chuyển sang app khác lâu đến mức hệ thống dừng process của app. Chữ "Ana" còn ở bước nào? Đổi sang `rememberSaveable` thì sao? Giữ trong ViewModel thì sao?', 'A sign-up screen has a "Name" field held with `remember { mutableStateOf("") }`. The user types "Ana", rotates the phone, then switches to another app long enough for the system to kill the app\'s process. After which step is "Ana" still there? With `rememberSaveable`? Kept in a ViewModel?')
    B(C, S, 1, 'ans', '`remember`: mất ngay khi xoay. `rememberSaveable`: còn sau khi xoay và sau khi process bị dừng (nó đi qua saved instance state). ViewModel (StateFlow thường): còn sau khi xoay, mất khi process bị dừng; cần `SavedStateHandle` mới còn. Mô phỏng của chương chạy đủ năm nơi giữ với bốn sự kiện.', '`remember`: lost as soon as the phone rotates. `rememberSaveable`: kept after the rotation and after the process kill (it goes through saved instance state). A ViewModel (plain StateFlow): kept after the rotation, lost on the process kill; it needs `SavedStateHandle` to survive. The chapter\'s simulation runs all five holders against four events.')

    S = 'loop'
    a(C + '.sec.%s.title' % S, 'Vòng cập nhật UI và luồng dữ liệu một chiều', 'The UI update loop and unidirectional data flow')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Sách Compose by Tutorials ví tương tác với app như một cuộc hội thoại, và tách thành vòng cập nhật UI ba bước. Sự kiện: người dùng (hoặc hệ thống) tạo đầu vào. Cập nhật state: một handler phản ứng và có thể đổi state. Hiển thị state: UI cập nhật theo state mới. Mọi app Android đều chạy vòng này; khác nhau ở chỗ ai sở hữu state. [[src:book-compose-tut]]', 'Compose by Tutorials compares using an app to a conversation, and splits it into a three-step UI update loop. Event: the user (or the system) generates input. Update state: a handler reacts and may change state. Display state: the UI updates to the new state. Every Android app runs this loop; they differ in who owns the state. [[src:book-compose-tut]]')
    B(C, S, 2, 'p', 'Trong hệ View, widget vừa hiển thị vừa giữ state (TextView giữ chữ, Spinner giữ lựa chọn), nên sách liệt kê các rắc rối: khó test vì state lẫn trong Activity/Fragment; dễ cập nhật state thiếu một phần; dễ quên cập nhật một phần UI; không có một nguồn sự thật duy nhất vì cả UI lẫn model đều giữ state; và không rõ ai đổi state (code hay người dùng). [[src:book-compose-tut]]', 'In the View system, widgets both display and hold state (a TextView holds its text, a Spinner its selection), so the book lists the troubles: hard to test because state is mixed into Activities/Fragments; easy to update only part of the state; easy to forget part of the UI; no single source of truth because both UI and model hold state; and unclear who changed the state (code or the user). [[src:book-compose-tut]]')
    B(C, S, 3, 'p', 'Luồng dữ liệu một chiều (unidirectional data flow, UDF): state đi XUỐNG, sự kiện đi LÊN. Composable cha giữ state, truyền giá trị cho con cùng một lambda xử lý sự kiện; con gọi lambda thay vì tự sửa state. Lợi ích theo sách: test từng phần riêng; state chỉ đổi ở một chỗ nên khó sai lệch; UI luôn phản ánh state; một nguồn sự thật; trách nhiệm cập nhật rõ ràng. Compose được thiết kế cho UDF ngay từ đầu. [[src:book-compose-tut]] [[src:and-state]]', 'Unidirectional data flow (UDF): state flows DOWN, events flow UP. The parent composable holds the state and passes a value to the child together with an event-handling lambda; the child calls the lambda instead of changing the state itself. The benefits per the book: test each part separately; state changes in one place, so it is hard to get inconsistent; the UI always reflects state; one source of truth; clear update responsibility. Compose was designed for UDF from the start. [[src:book-compose-tut]] [[src:and-state]]')
    B(C, S, 4, 'kt', '// Ví dụ của Jetpack Compose 1.3 Essentials: FunctionA giữ state, FunctionB chỉ báo sự kiện\n@Composable\nfun FunctionA() {\n    var switchState by remember { mutableStateOf(true) }\n    FunctionB(\n        switchState = switchState,                       // state đi xuống\n        onSwitchChange = { switchState = it }            // sự kiện đi lên\n    )\n}\n\n@Composable\nfun FunctionB(switchState: Boolean, onSwitchChange: (Boolean) -> Unit) {\n    Switch(checked = switchState, onCheckedChange = onSwitchChange)\n}', '// The Jetpack Compose 1.3 Essentials example: FunctionA holds the state, FunctionB only reports events\n@Composable\nfun FunctionA() {\n    var switchState by remember { mutableStateOf(true) }\n    FunctionB(\n        switchState = switchState,                       // state flows down\n        onSwitchChange = { switchState = it }            // events flow up\n    )\n}\n\n@Composable\nfun FunctionB(switchState: Boolean, onSwitchChange: (Boolean) -> Unit) {\n    Switch(checked = switchState, onCheckedChange = onSwitchChange)\n}')

    S = 'stateless'
    a(C + '.sec.%s.title' % S, 'Stateful và stateless', 'Stateful and stateless')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Theo Kunneth, một composable là STATEFUL nếu nó giữ (remember) một giá trị, và STATELESS nếu nó không giữ gì: nó có thể nhận state qua tham số nhưng không lưu và không `remember` gì khác. Composable stateless gọi lại với cùng đối số thì cho cùng kết quả (idempotent), nên dễ dùng lại và dễ test: nó không dựa vào thứ gì ngoài tham số. [[src:book-kunneth]]', 'Per Kunneth, a composable is STATEFUL if it keeps (remembers) a value, and STATELESS if it keeps nothing: it may receive state through parameters but neither stores it nor `remember`s anything else. A stateless composable called again with the same arguments gives the same result (idempotent), so it is easy to reuse and test: it relies on nothing beyond its parameters. [[src:book-kunneth]]')
    B(C, S, 2, 'p', 'Mẫu thường gặp: viết bản stateless làm lõi, và một bản stateful tiện dụng bọc ngoài cho người gọi không quan tâm tới state. Kunneth làm vậy với `TextFieldDemo`; tài liệu chỉ ra chính `LazyColumn` cũng thế: tham số `state` có giá trị mặc định `rememberLazyListState()`, nên ai cần điều khiển thì truyền vào, ai không cần thì bỏ qua (hữu ích khi test hay preview). [[src:book-kunneth]] [[src:cp-hoisting]]', 'A common pattern: write the stateless version as the core, plus a convenient stateful wrapper for callers who do not care about the state. Kunneth does this with `TextFieldDemo`; the docs point out `LazyColumn` itself works this way: its `state` parameter defaults to `rememberLazyListState()`, so callers who need control pass one in and others skip it (handy in tests and previews). [[src:book-kunneth]] [[src:cp-hoisting]]')
    B(C, S, 3, 'kt', '// lõi stateless: nhận giá trị và sự kiện\n@Composable\nfun NameField(name: String, onNameChange: (String) -> Unit, modifier: Modifier = Modifier) {\n    OutlinedTextField(value = name, onValueChange = onNameChange, label = { Text("Name") }, modifier = modifier)\n}\n\n// bản stateful tiện dụng\n@Composable\nfun NameField(modifier: Modifier = Modifier) {\n    var name by rememberSaveable { mutableStateOf("") }\n    NameField(name, onNameChange = { name = it }, modifier)\n}', '// the stateless core: takes a value and an event\n@Composable\nfun NameField(name: String, onNameChange: (String) -> Unit, modifier: Modifier = Modifier) {\n    OutlinedTextField(value = name, onValueChange = onNameChange, label = { Text("Name") }, modifier = modifier)\n}\n\n// the convenient stateful version\n@Composable\nfun NameField(modifier: Modifier = Modifier) {\n    var name by rememberSaveable { mutableStateOf("") }\n    NameField(name, onNameChange = { name = it }, modifier)\n}')
    B(C, S, 4, 'note', 'Kunneth truyền `MutableState<String>` vào composable con (`TemperatureTextField(temperature: MutableState<String>)`) để con tự ghi. Cách đó chạy được, nhưng tài liệu hiện tại khuyên chủ state đưa ra state BẤT BIẾN cùng sự kiện để sửa nó: truyền `String` và `(String) -> Unit`. Con không thể ghi state của cha theo cách cha không biết. [[src:book-kunneth]] [[src:cp-hoisting]]', 'Kunneth passes a `MutableState<String>` to the child composable (`TemperatureTextField(temperature: MutableState<String>)`) so the child writes it itself. That works, but current docs advise the state owner to expose IMMUTABLE state plus events to modify it: pass a `String` and a `(String) -> Unit`. Then the child cannot write the parent\'s state in ways the parent does not know about. [[src:book-kunneth]] [[src:cp-hoisting]]')
    a(C + '.sec.%s.b.04.kind' % S, 'source')

    S = 'hoist'
    a(C + '.sec.%s.title' % S, 'Hoist state lên đâu', 'Where to hoist state')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Hoisting là dời state từ một composable lên người gọi (hoặc cao hơn) để composable đó thành stateless. Ngoài dễ dùng lại và dễ test, hoisting là CẦN THIẾT khi nhiều composable cùng dùng một state: trong ví dụ của Essentials, cả `NameField` và `NameText` cần cùng một tên, nên state phải ở tổ tiên chung `MainScreen`. [[src:book-compose-ess]]', 'Hoisting moves state from a composable up to its caller (or higher) so the composable becomes stateless. Besides reuse and testing, hoisting is NECESSARY when several composables use the same state: in the Essentials example, both `NameField` and `NameText` need the same name, so the state must live in their common ancestor `MainScreen`. [[src:book-compose-ess]]')
    B(C, S, 2, 'p', 'Ba luật của tài liệu: (1) hoist ít nhất tới cha chung thấp nhất của mọi composable ĐỌC state; (2) ít nhất tới mức cao nhất nơi state có thể bị GHI; (3) hai state đổi theo cùng sự kiện thì hoist cùng nhau. Hoist cao hơn mức cần thì vẫn chạy, nhưng hoist thiếu thì khó hoặc không thể theo UDF. Giữ state gần nơi dùng nhất có thể, và đừng truyền nó cho composable không cần. [[src:and-state]] [[src:cp-hoisting]]', 'The docs\' three rules: (1) hoist at least to the lowest common parent of every composable that READS the state; (2) at least to the highest level where it may be WRITTEN; (3) if two states change in response to the same events, hoist them together. Hoisting higher than needed still works, but underhoisting makes UDF hard or impossible. Keep state as close as possible to where it is consumed, and do not pass it to composables that do not need it. [[src:and-state]] [[src:cp-hoisting]]')
    B(C, S, 3, 'p', 'Sự kiện cũng đi lên: trong ứng dụng đổi nhiệt độ của Kunneth, cú bấm `RadioButton` không xử lý tại chỗ mà được chuyển lên `TemperatureScaleButtonGroup` (sự kiện "nổi lên"); phép chuyển đổi được viết một lần thành lambda `calc` và truyền cho cả ô nhập (nút Done của bàn phím) lẫn nút "Convert". Truyền mã xử lý sự kiện làm tham số thay vì viết cứng bên trong làm composable dễ dùng lại và dễ test. [[src:book-kunneth]]', 'Events flow up too: in Kunneth\'s temperature converter, a `RadioButton` click is not handled on the spot but passed up to `TemperatureScaleButtonGroup` (the event "bubbles up"); the conversion is written once as a `calc` lambda and passed to both the text field (the keyboard\'s Done action) and the "Convert" button. Passing event-handling code as a parameter instead of hard-coding it makes composables easier to reuse and test. [[src:book-kunneth]]')
    B(C, S, 4, 'ask', 'Màn hình chat có danh sách tin nhắn (`LazyColumn`) và nút "Xuống cuối". Ô nhập gửi tin xong cũng phải cuộn xuống cuối. `LazyListState` nên nằm ở đâu?', 'A chat screen has a message list (`LazyColumn`) and a "Jump to bottom" button. Sending from the input field must also scroll to the bottom. Where should the `LazyListState` live?')
    B(C, S, 4, 'ans', 'Ở `ConversationScreen`, tổ tiên chung thấp nhất của danh sách, nút và ô nhập (ví dụ của tài liệu). Nó được tạo bằng `rememberLazyListState()` trong composable đó, nên sống theo Composition. Danh sách vẫn giữ tham số `state` có giá trị mặc định để dùng được ở nơi khác. [[src:cp-hoisting]]', 'In `ConversationScreen`, the lowest common ancestor of the list, the button and the input (the docs\' example). It is created with `rememberLazyListState()` in that composable, so it lives with the Composition. The list keeps a `state` parameter with a default so it can be used elsewhere. [[src:cp-hoisting]]')

    S = 'owners'
    a(C + '.sec.%s.title' % S, 'Ai giữ state: composable, state holder hay ViewModel', 'Who owns state: a composable, a state holder or a ViewModel')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Tài liệu chia hai loại UI state. Screen UI state là thứ cần hiện trên màn hình, thường đến từ dữ liệu app (ví dụ `NewsUiState`). UI element state là thuộc tính của một phần tử UI: đang mở hay đóng, vị trí cuộn, chữ trong ô nhập. Và hai loại logic: business logic thực hiện yêu cầu sản phẩm trên dữ liệu (lưu bookmark), UI logic là cách hiển thị (gợi ý nào trong ô tìm kiếm, cuộn tới đâu, điều hướng). [[src:cp-hoisting]]', 'The docs split UI state in two. Screen UI state is what must appear on screen, usually from app data (for example `NewsUiState`). UI element state is a property of a UI element: expanded or collapsed, scroll position, the text in a field. And two kinds of logic: business logic implements product requirements on data (saving a bookmark); UI logic is how things are displayed (which search hint, where to scroll, navigation). [[src:cp-hoisting]]')
    B(C, S, 2, 'p', 'Từ đó: (1) UI logic đơn giản và state không ai khác cần → để composable tự giữ, không cần hoist (ví dụ `showDetails` của một bong bóng chat); (2) cần chia sẻ → hoist trong cây composable tới tổ tiên chung thấp nhất; (3) UI logic phức tạp trên một hay nhiều state → một plain state holder class được tạo và `remember` trong Composition, như `LazyListState`; (4) business logic hoặc screen UI state → ViewModel, sống NGOÀI Composition, gắn với một `ViewModelStoreOwner` (Activity, Fragment, đích điều hướng). [[src:cp-hoisting]]', 'Hence: (1) simple UI logic and state nobody else needs → let the composable own it, no hoisting (for example a chat bubble\'s `showDetails`); (2) needs sharing → hoist within the composable tree to the lowest common ancestor; (3) complex UI logic over one or more states → a plain state holder class created and `remember`ed in the Composition, like `LazyListState`; (4) business logic or screen UI state → a ViewModel, living OUTSIDE the Composition, scoped to a `ViewModelStoreOwner` (Activity, Fragment, navigation destination). [[src:cp-hoisting]]')
    B(C, S, 3, 'kt', 'class ConversationViewModel(private val repo: MessagesRepository) : ViewModel() {\n    val messages: StateFlow<List<Message>> = repo.messages\n        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())\n    fun send(text: String) { viewModelScope.launch { repo.send(text) } }\n}\n\n@Composable\nfun ConversationScreen(vm: ConversationViewModel = viewModel()) {     // chỉ màn hình cấp cao nhận ViewModel\n    val messages by vm.messages.collectAsStateWithLifecycle()\n    ConversationContent(messages = messages, onSend = vm::send)      // con nhận dữ liệu và lambda\n}', 'class ConversationViewModel(private val repo: MessagesRepository) : ViewModel() {\n    val messages: StateFlow<List<Message>> = repo.messages\n        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())\n    fun send(text: String) { viewModelScope.launch { repo.send(text) } }\n}\n\n@Composable\nfun ConversationScreen(vm: ConversationViewModel = viewModel()) {     // only the screen-level composable gets the ViewModel\n    val messages by vm.messages.collectAsStateWithLifecycle()\n    ConversationContent(messages = messages, onSend = vm::send)      // children get data and lambdas\n}')
    B(C, S, 4, 'p', 'Ba lời khuyên kèm theo của tài liệu. Đừng truyền instance ViewModel xuống các composable con. "Property drilling" (truyền dữ liệu và lambda qua nhiều tầng) được ưa hơn việc gói state và sự kiện vào một lớp wrapper, vì chữ ký hàm cho thấy ngay composable làm gì. Và chỉ hoist UI element state lên ViewModel khi business logic thật sự cần đọc hay ghi nó. [[src:cp-hoisting]]', 'Three accompanying tips from the docs. Do not pass ViewModel instances down to child composables. "Property drilling" (passing data and lambdas through several levels) is preferred over wrapping state and events in one class, because the function signature shows at a glance what the composable does. And hoist UI element state to the ViewModel only when business logic really needs to read or write it. [[src:cp-hoisting]]')
    B(C, S, 5, 'note', 'Lưu ý của tài liệu: một số state holder của phần tử UI có hàm suspend chạy animation (ví dụ `DrawerState.close()`). Gọi nó từ `viewModelScope` ném `IllegalStateException` "a MonotonicFrameClock is not available in this CoroutineContext". Cần một `CoroutineScope` gắn với Composition (`rememberCoroutineScope()`), vì scope đó có frame clock. Chương B5 nói về frame clock. [[src:cp-hoisting]]', 'A caveat from the docs: some UI element state holders have suspend functions that run animations (for example `DrawerState.close()`). Calling one from `viewModelScope` throws an `IllegalStateException`, "a MonotonicFrameClock is not available in this CoroutineContext". It needs a `CoroutineScope` scoped to the Composition (`rememberCoroutineScope()`), because that scope has a frame clock. Chapter B5 covers the frame clock. [[src:cp-hoisting]]')
    a(C + '.sec.%s.b.05.kind' % S, 'pitfall')
    B(C, S, 6, 'note', 'Ví dụ ViewModel của Kunneth và Tutorials dùng `LiveData` cùng `observeAsState()` (lifecycle 2.4.0 trong sách của Kunneth). Đó là phiên bản của sách. Mẫu hiện tại trong tài liệu Android là `StateFlow` cùng `collectAsStateWithLifecycle()`, như đoạn mã trên. [[src:book-kunneth]] [[src:book-compose-tut]]', 'The ViewModel examples in Kunneth and Tutorials use `LiveData` with `observeAsState()` (lifecycle 2.4.0 in Kunneth\'s book). That is the books\' version. The current pattern in the Android docs is `StateFlow` with `collectAsStateWithLifecycle()`, as in the code above. [[src:book-kunneth]] [[src:book-compose-tut]]')
    a(C + '.sec.%s.b.06.kind' % S, 'source')

    S = 'survive'
    a(C + '.sec.%s.title' % S, 'Sống qua đổi cấu hình và process death', 'Surviving configuration changes and process death')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Hai sự kiện làm app mất UI state. Đổi cấu hình (xoay màn hình, đổi ngôn ngữ…): activity bị hủy và tạo lại, trừ khi app tự xử lý thay đổi đó. Process bị hệ thống dừng: app ở nền, thiết bị cần tài nguyên. Khác với việc người dùng chủ động đóng hẳn activity: khi đó mất state tạm (chữ trong form, trạng thái animation) thường là hợp lý. Tối thiểu nên giữ input của người dùng và state điều hướng: vị trí cuộn, id mục đang xem, lựa chọn đang làm dở, chữ trong ô nhập. [[src:cp-saving]]', 'Two events make an app lose UI state. A configuration change (rotation, a language change…): the activity is destroyed and recreated unless the app handles that change itself. System-initiated process death: the app is in the background and the device needs resources. This differs from the user deliberately dismissing the activity: then losing transient state (form text, animation state) is usually reasonable. At minimum, preserve user input and navigation state: scroll position, the id of the item being viewed, an in-progress selection, text in fields. [[src:cp-saving]]')
    B(C, S, 2, 'p', '`rememberSaveable` giống `remember` nhưng còn lưu giá trị vào saved instance state (một `Bundle`), nên sống qua đổi cấu hình và process death. Kiểu nguyên thủy được lưu tự động; kiểu khác cần `@Parcelize`, `mapSaver`/`listSaver`, hoặc một `Saver` tự viết. `rememberLazyListState()` chính là dùng `rememberSaveable` với `LazyListState.Saver`. Bundle có giới hạn kích thước và dùng chung với các API khác như `onSaveInstanceState()`; lưu đối tượng lớn có thể gây `TransactionTooLargeException`. Hãy lưu tối thiểu (id, key) và khôi phục phần còn lại từ lưu trữ bền. Kiểm bằng `StateRestorationTester`. [[src:cp-saving]] [[src:and-state]]', '`rememberSaveable` is like `remember` but also saves the value into saved instance state (a `Bundle`), so it survives configuration changes and process death. Primitive types are saved automatically; other types need `@Parcelize`, `mapSaver`/`listSaver`, or a custom `Saver`. `rememberLazyListState()` itself uses `rememberSaveable` with `LazyListState.Saver`. The Bundle has a size limit and is shared with other APIs such as `onSaveInstanceState()`; storing large objects can cause a `TransactionTooLargeException`. Save the minimum (ids, keys) and restore the rest from durable storage. Verify with `StateRestorationTester`. [[src:cp-saving]] [[src:and-state]]')
    B(C, S, 3, 'kt', '@Parcelize\ndata class City(val name: String, val country: String) : Parcelable\n\nval CitySaver = mapSaver(\n    save = { mapOf("name" to it.name, "country" to it.country) },\n    restore = { City(it["name"] as String, it["country"] as String) }\n)\n\n@Composable\nfun CityScreen() {\n    var city by rememberSaveable(stateSaver = CitySaver) { mutableStateOf(City("Madrid", "Spain")) }\n}')
    B(C, S, 4, 'p', 'ViewModel sống qua đổi cấu hình: instance cũ được gắn vào activity mới. Nhưng tài liệu nhấn mạnh: hoist state lên ViewModel vì kiến trúc hợp lý, không phải vì nó "miễn phí" qua đổi cấu hình. ViewModel KHÔNG sống qua process death do hệ thống; state cần sống qua đó dùng `SavedStateHandle` (Saved State module). [[src:cp-saving]]', 'A ViewModel survives configuration changes: the old instance is attached to the new activity. But the docs stress: hoist state into the ViewModel because it makes architectural sense, not because it survives configuration changes "for free". A ViewModel does NOT survive system-initiated process death; state that must survive it uses `SavedStateHandle` (the Saved State module). [[src:cp-saving]]')
    B(C, S, 5, 'predict', 'Trong mô phỏng ngay dưới, chọn "Hệ thống dừng process khi app ở nền". Trong năm nơi giữ, nơi nào còn "Ana"?', 'In the simulation just below, pick "The system kills the process while the app is in the background". Of the five holders, which still have "Ana"?')
    B(C, S, 5, 'ans', 'Ba nơi: `rememberSaveable`, `SavedStateHandle`, lưu trữ bền. `remember` và StateFlow thường trong ViewModel nằm trong bộ nhớ nên mất.', 'Three: `rememberSaveable`, `SavedStateHandle`, durable storage. `remember` and the plain StateFlow in the ViewModel live in memory, so they are lost.')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Xoay màn hình là ô tìm kiếm trống và danh sách cuộn về đầu.', 'Rotating the screen empties the search field and scrolls the list back to the top.')
    B(C, S, 1, 'cause', 'Chữ tìm kiếm giữ bằng `remember`; `LazyListState` tự tạo bằng `remember { LazyListState() }` thay vì `rememberLazyListState()`.', 'The query is held with `remember`; the `LazyListState` is created with `remember { LazyListState() }` instead of `rememberLazyListState()`.')
    B(C, S, 1, 'fix', '`var query by rememberSaveable { mutableStateOf("") }` và `rememberLazyListState()` (đã dùng `rememberSaveable` bên trong). Nếu chữ tìm kiếm còn dùng cho business logic (gợi ý từ dữ liệu), giữ nó trong ViewModel với `SavedStateHandle`.', '`var query by rememberSaveable { mutableStateOf("") }` and `rememberLazyListState()` (which already uses `rememberSaveable` inside). If the query also feeds business logic (suggestions from data), keep it in the ViewModel with `SavedStateHandle`.')
    B(C, S, 2, 'bug', 'App crash với `TransactionTooLargeException` khi chuyển sang nền, chỉ trên vài màn hình.', 'The app crashes with `TransactionTooLargeException` when going to the background, only on some screens.')
    B(C, S, 2, 'cause', '`rememberSaveable` được dùng để lưu cả danh sách sản phẩm (hàng trăm đối tượng `@Parcelize`) vào Bundle.', '`rememberSaveable` is used to save a whole product list (hundreds of `@Parcelize` objects) into the Bundle.')
    B(C, S, 2, 'fix', 'Chỉ lưu id/khóa cần thiết (ví dụ id mục đang chọn, chữ tìm kiếm); danh sách tải lại từ repository/Room. [[src:cp-saving]]', 'Save only the ids/keys needed (for example the selected item\'s id, the query); reload the list from the repository/Room. [[src:cp-saving]]')
    B(C, S, 3, 'bug', 'Bấm vào một mục để đóng ngăn kéo (drawer) thì app crash với "a MonotonicFrameClock is not available in this CoroutineContext".', 'Tapping an item to close the drawer crashes the app with "a MonotonicFrameClock is not available in this CoroutineContext".')
    B(C, S, 3, 'cause', 'ViewModel giữ `DrawerState` và gọi `drawerState.close()` trong `viewModelScope.launch`. `close()` chạy animation, cần frame clock, mà `viewModelScope` không có. [[src:cp-hoisting]]', 'The ViewModel holds the `DrawerState` and calls `drawerState.close()` in `viewModelScope.launch`. `close()` runs an animation and needs a frame clock, which `viewModelScope` lacks. [[src:cp-hoisting]]')
    B(C, S, 3, 'fix', 'Gọi `close()` từ một scope gắn với Composition: `val scope = rememberCoroutineScope()` trong composable, hoặc truyền scope đó vào hàm của ViewModel như tài liệu làm.', 'Call `close()` from a Composition-scoped scope: `val scope = rememberCoroutineScope()` in the composable, or pass that scope into the ViewModel function as the docs do.')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Tách composable stateful này thành một lõi stateless và một bản stateful, theo UDF:', 'Split this stateful composable into a stateless core and a stateful wrapper, following UDF:')
    B(C, S, 1, 'exkt', '@Composable\nfun Rating() {\n    var stars by remember { mutableStateOf(0) }\n    Row {\n        for (i in 1..5) {\n            IconButton(onClick = { stars = i }) {\n                Icon(if (i <= stars) Icons.Filled.Star else Icons.Outlined.Star, contentDescription = "$i")\n            }\n        }\n    }\n}')
    B(C, S, 1, 'hint', 'Lõi nhận `stars: Int` và `onStarsChange: (Int) -> Unit`. Bản stateful giữ state (nên dùng `rememberSaveable`) và gọi lõi.', 'The core takes `stars: Int` and `onStarsChange: (Int) -> Unit`. The stateful version holds the state (preferably with `rememberSaveable`) and calls the core.')
    B(C, S, 1, 'solkt', '@Composable\nfun Rating(stars: Int, onStarsChange: (Int) -> Unit, modifier: Modifier = Modifier) {\n    Row(modifier) {\n        for (i in 1..5) {\n            IconButton(onClick = { onStarsChange(i) }) {\n                Icon(if (i <= stars) Icons.Filled.Star else Icons.Outlined.Star, contentDescription = "$i")\n            }\n        }\n    }\n}\n\n@Composable\nfun Rating(modifier: Modifier = Modifier) {\n    var stars by rememberSaveable { mutableStateOf(0) }\n    Rating(stars, onStarsChange = { stars = it }, modifier)\n}')
    B(C, S, 1, 'sol', 'Lõi stateless có thể dùng trong preview với bất kỳ số sao nào và test bằng cách kiểm lambda được gọi với giá trị đúng.', 'The stateless core can be previewed with any number of stars and tested by checking the lambda is called with the right value.')
    B(C, S, 2, 'ex', 'Màn hình giỏ hàng có: số lượng từng món (từ repository), ô mã giảm giá đang gõ, cờ "đang mở phần chi tiết thanh toán". Mỗi thứ nên do ai giữ, và dùng API nào để sống qua xoay màn hình?', 'A cart screen has: the quantity of each item (from the repository), a discount code being typed, a flag "payment details expanded". Who should own each, and which API keeps it across rotation?')
    B(C, S, 2, 'sol', 'Số lượng: screen UI state từ business logic → ViewModel (`StateFlow` từ repository); sống qua xoay nhờ ViewModel, qua process death nhờ dữ liệu bền. Mã giảm giá: nếu chỉ hiện trong ô nhập thì `rememberSaveable` trong UI; nếu business logic cần kiểm mã khi gõ thì đưa vào ViewModel với `SavedStateHandle`. Cờ mở/đóng: UI element state đơn giản → `rememberSaveable` trong composable đó.', 'Quantities: screen UI state from business logic → the ViewModel (a `StateFlow` from the repository); survives rotation via the ViewModel and process death via durable data. The discount code: if it only lives in the field, `rememberSaveable` in the UI; if business logic validates it while typing, move it into the ViewModel with `SavedStateHandle`. The expanded flag: simple UI element state → `rememberSaveable` in that composable.')
    B(C, S, 3, 'ex', 'Theo ba luật hoist: `SearchBar` ghi chữ tìm kiếm, `ResultsList` và `ResultsCount` đọc nó, cả ba là con của `SearchScreen`; `FilterChips` cũng đổi chữ tìm kiếm và nằm trong `TopBar`, con của `SearchScreen`. State nên ở đâu?', 'Per the three hoisting rules: `SearchBar` writes the query, `ResultsList` and `ResultsCount` read it, all three children of `SearchScreen`; `FilterChips` also changes the query and lives in `TopBar`, a child of `SearchScreen`. Where should the state go?')
    B(C, S, 3, 'sol', 'Ở `SearchScreen`: đó là cha chung thấp nhất của mọi nơi đọc (luật 1) và cũng là mức cao nhất có nơi ghi (`SearchBar`, `FilterChips` qua `TopBar`, luật 2). `TopBar` nhận lambda `onQueryChange` để chuyển tiếp cho `FilterChips`.', 'In `SearchScreen`: it is the lowest common parent of every reader (rule 1) and also the highest level with a writer (`SearchBar`, `FilterChips` via `TopBar`, rule 2). `TopBar` receives an `onQueryChange` lambda to pass on to `FilterChips`.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'UDF là gì, và composable con báo thay đổi lên cha bằng cách nào?', 'What is UDF, and how does a child composable report a change to its parent?')
    B(C, S, 1, 'ans', 'State đi xuống, sự kiện đi lên. Con nhận giá trị và một lambda; khi có sự kiện, con gọi lambda; cha (chủ state) quyết định cập nhật.', 'State flows down, events flow up. The child receives a value and a lambda; on an event it calls the lambda; the parent (the state owner) decides how to update.')
    B(C, S, 2, 'ask', 'Ba luật hoist của tài liệu?', 'The docs\' three hoisting rules?')
    B(C, S, 2, 'ans', 'Ít nhất tới cha chung thấp nhất của mọi nơi đọc; ít nhất tới mức cao nhất nơi state bị ghi; hai state đổi theo cùng sự kiện thì hoist cùng nhau.', 'At least to the lowest common parent of all readers; at least to the highest level where it is written; two states changing on the same events are hoisted together.')
    B(C, S, 3, 'ask', 'So sánh `remember`, `rememberSaveable`, ViewModel và `SavedStateHandle` về đổi cấu hình và process death.', 'Compare `remember`, `rememberSaveable`, ViewModel and `SavedStateHandle` for configuration changes and process death.')
    B(C, S, 3, 'ans', '`remember`: mất ở cả hai. `rememberSaveable`: qua cả hai. ViewModel: qua đổi cấu hình, mất khi process death. `SavedStateHandle`: qua cả hai. Không cái nào qua việc người dùng đóng hẳn app.', '`remember`: lost in both. `rememberSaveable`: survives both. ViewModel: survives configuration changes, lost on process death. `SavedStateHandle`: survives both. None survives the user closing the app for good.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Composable nhận `state: State<String>` và chỉ đọc nó có phải stateless không?', 'Is a composable that receives `state: State<String>` and only reads it stateless?',
         'Có.', 'Yes.', 'Nó nhận state qua tham số nhưng không lưu và không `remember` gì (Kunneth).', 'It receives state through a parameter but neither stores it nor `remember`s anything (Kunneth).'),
        ('q2', 'Có nên truyền ViewModel xuống các composable con?', 'Should you pass the ViewModel down to child composables?',
         'Không.', 'No.', 'Màn hình cấp cao nhận ViewModel; con nhận dữ liệu và lambda.', 'The screen-level composable gets the ViewModel; children get data and lambdas.'),
        ('q3', '`rememberSaveable` có giữ state khi người dùng vuốt app khỏi màn hình gần đây?', 'Does `rememberSaveable` keep state when the user swipes the app away from recents?',
         'Không.', 'No.', 'Tài liệu ghi rõ nó không giữ khi activity bị người dùng đóng hẳn.', 'The docs state it does not retain state when the user fully dismisses the activity.'),
        ('q4', 'Lưu cả danh sách 500 đối tượng bằng `rememberSaveable` có ổn không?', 'Is saving a whole list of 500 objects with `rememberSaveable` fine?',
         'Không.', 'No.', 'Bundle có giới hạn kích thước; lưu id rồi tải lại dữ liệu từ lưu trữ bền.', 'The Bundle has a size limit; save ids and reload the data from durable storage.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
